class Buffer {
private:
    std::vector<std::byte> buf_; 
    std::atomic<std::size_t> read_pos_; 
    std::atomic<std::size_t> write_pos_; 

public:
    Buffer(std::size_t size) noexcept : buf_(size), read_pos_(0), write_pos_(0) {}
    Buffer(std::span<const std::byte> bytes) noexcept : buf_(bytes.begin(), bytes.end()), read_pos_(0), write_pos_(static_cast<std::size_t>(bytes.size())) {}
    Buffer(std::initializer_list<std::byte> bytes) noexcept : buf_(bytes), read_pos_(0), write_pos_(static_cast<std::size_t>(bytes.size())) {}
    Buffer(std::string_view str) noexcept : buf_(str.begin(), str.end()), read_pos_(0), write_pos_(static_cast<std::size_t>(str.size())) {}
    Buffer(const Buffer& o) noexcept : buf_(o.buf_), read_pos_(o.read_pos_), write_pos_(o.write_pos_) {}
    Buffer(Buffer&& o) noexcept : buf_(std::move(o.buf_)), read_pos_(o.read_pos_), write_pos_(o.write_pos_)
    {
        o.read_pos_ = 0;
        o.write_pos_ = 0;
    }

    operator=(const Buffer& o) noexcept {
        if (this != &o) {
            buf_ = o.buf_; 
            read_pos_ = o.read_pos_; 
            write_pos_ = o.write_pos_;
        }
        return *this;
    }

    operator=(Buffer&& o) noexcept {
        if (this != &o) {
            buf_ = std::move(o.buf_);
            read_pos_ = o.read_pos_; 
            write_pos_ = o.write_pos_;
            o.read_pos_ = 0;
            o.write_pos_ = 0;
        }
        return *this;
    }

    std::size_t WritableSize() const noexcept {
        return buf_.size() - write_pos_; 
    }

    std::size_t ReadableSize() const noexcept {
        return write_pos_ - read_pos_; 
    }

    std::optional<std::byte> Peek() const noexcept {
        if (read_pos_ < write_pos_) {
            return buf_[read_pos_];
        } else {
            return std::nullopt;
        }
    }

    std::span<const std::byte> ReadableBytes() const noexcept {
        return std::span<const std::byte>(buf_.data() + read_pos_, write_pos_ - read_pos_);
    }

    std::string ReadableString() const noexcept {
        return std::string(ReadableBytes().begin(), ReadableBytes().end());
    }

    std::span<const std::byte> WritableBytes() const noexcept {
        return std::span<const std::byte>(buf_.data() + write_pos_, buf_.size() - write_pos_);
    }

    void Append(std::span<const std::byte> bytes) noexcept {
        EnsureWriteableSize(bytes.size());
        std::copy(bytes.begin(), bytes.end(), WriteIter());
        write_pos_.fetch_add(bytes.size(), std::memory_order_seq_cst);
    }

    void Append(std::initializer_list<std::byte> bytes) noexcept {
        Append(std::span<const std::byte>(bytes));
    }

    void Append(std::string_view str, std::optional<NewLine> new_line = std::nullopt) noexcept {
        if (new_line.has_value()) {
            Append(str);
            Append(static_cast<std::byte>(new_line.value()));
        } else {
            Append(str);
        }
    }

    void Append(const void* data, std::size_t size) noexcept {
        EnsureWriteableSize(size);
        std::copy(static_cast<const std::byte*>(data), static_cast<const std::byte*>(data) + size, WriteIter());
        write_pos_.fetch_add(size, std::memory_order_seq_cst);
    }

    void Append(const Buffer& buf) noexcept {
        Append(buf.ReadableBytes());
    }

    void EnsureWriteableSize(std::size_t size) noexcept {
        if (WritableSize() < size) {
            buf_.reserve(write_pos_ + size);
        }
    }

    void HasWritten(std::size_t size) noexcept {
        read_pos_.fetch_add(size, std::memory_order_seq_cst);
    }

    void Retrieve(std::size_t size) noexcept {
        if (size > ReadableSize()) {
            size = ReadableSize();
        }
        read_pos_.fetch_add(size, std::memory_order_seq_cst);
    }

    void RetrieveUntil(const void* addr) noexcept {
        auto it = std::find(ReadIter(), WriteIter(), static_cast<std::byte*>(addr));
        if (it != WriteIter()) {
            size_t size = std::distance(ReadIter(), it);
            Retrieve(size);
        }
    }

    void RetrieveAll() noexcept {
        read_pos_.store(0, std::memory_order_seq_cst);
        write_pos_.store(0, std::memory_order_seq_cst);
    }

    std::string RetrieveAllToString() noexcept {
        std::string result(ReadableBytes().begin(), ReadableBytes().end());
        RetrieveAll();
        return result;
    }

    void Clear() noexcept {
        RetrieveAll();
    }

    bool Empty() const noexcept {
        return ReadableSize() == 0;
    }

protected:
    std::size_t PrependableSize() const noexcept {
        return read_pos_; 
    }

    void MakeSpace(std::size_t size) noexcept {
        buf_.reserve(write_pos_ + size);
    }

    auto ReadIter() noexcept {
        return buf_.begin() + read_pos_;
    }

    auto WriteIter() noexcept {
        return buf_.begin() + write_pos_;
    }
};

class IOBuffer : public Buffer {
public:
    IOBuffer(const Buffer& buf) : Buffer(buf)
    {}

    std::size_t ReadFrom(ws::io::IReadWriter& io) noexcept {
        std::size_t read_size = io.ReadFrom(*this);
        return read_size;
    }

    std::size_t WriteTo(ws::io::IReadWriter& io) noexcept {
        std::size_t write_size = io.WriteTo(*this);
        return write_size;
    }
};
